class Solution {
    private ListNode reverse(ListNode head){
        ListNode previous=null;
        while(head!=null){
            ListNode next=head.next;
            head.next=previous;
            previous=head;
            head=next;
        }
        return previous;
    }
    public ListNode removeNodes(ListNode head){
        ListNode node=reverse(head),answer=null;
        int maximum=Integer.MIN_VALUE;
        while(node!=null){
            ListNode next=node.next;
            if(node.val>=maximum){
                maximum=node.val;
                node.next=answer;
                answer=node;
            }
            node=next;
        }
        return answer;
    }
}

